/** One table's screen: the rows, a create form for the columns a write may set,
 * and a delete button — each written only when the API actually offers it. */
function screenTsx(table) {
  const { pascal, pk } = table;
  const canCreate = table.ops.create;
  const canDelete = table.ops.delete && !!pk;
  const inputs = canCreate ? table.form.inputs : [];

  const rn = new Set(["ActivityIndicator", "Text", "View"]);
  if (canCreate || canDelete) rn.add("Pressable");
  if (inputs.some((f) => f.control === "checkbox")) rn.add("Switch");
  if (inputs.some((f) => f.control !== "checkbox")) rn.add("TextInput");

  const hooks = [`use${pascal}`];
  if (canCreate) hooks.push(`useCreate${pascal}`);
  if (canDelete) hooks.push(`useDelete${pascal}`);

  let imports = canCreate ? `import { useState } from "react";\n` : "";
  imports += importLine([...rn].sort(), "react-native") + "\n";
  imports += importLine(hooks, "../feldspar/hooks");
  imports += `import { styles } from "../theme";\n`;

  let body = `  const { data, error, loading } = use${pascal}();\n`;
  if (canCreate) {
    const empty = inputs.map((f) => `    ${f.name}: ${f.empty},`).join("\n");
    const minted = table.form.minted.map((n) => `${n}: crypto.randomUUID()`).join(", ");
    const argument = minted ? `{ ...form, ${minted} }` : `{ ...form }`;
    body += `  const create = useCreate${pascal}();
  const empty = {
${empty}
  };
  const [form, setForm] = useState({ ...empty });

  const add = async (): Promise<void> => {
    await create.run(${argument});
    setForm({ ...empty });
  };
`;
  }
  if (canDelete) body += `  const remove = useDelete${pascal}();\n`;

  let jsx = `      <Text style={styles.h1}>${table.title}</Text>\n`;
  if (canCreate) {
    const controls = inputs.map(formControl).join("\n");
    jsx += `      <View style={styles.card}>
${controls}
        <Pressable
          style={[styles.button, create.pending && styles.disabled]}
          disabled={create.pending}
          onPress={() => void add()}
        >
          <Text style={styles.buttonText}>Add</Text>
        </Pressable>
        {create.error ? <Text style={styles.error}>{create.error.message}</Text> : null}
      </View>
`;
  }
  if (canDelete) {
    jsx += `      {remove.error ? <Text style={styles.error}>{remove.error.message}</Text> : null}\n`;
  }
  const cells = table.fields
    .map(
      (f) => `                <Text style={styles.text}>
                  <Text style={styles.label}>${f.label}: </Text>
                  {String(row.${f.name} ?? "")}
                </Text>`,
    )
    .join("\n");
  const key = pk ? `String(row.${pk})` : "JSON.stringify(row)";
  const del = canDelete
    ? `
              <Pressable
                style={[styles.button, styles.buttonDanger]}
                onPress={() => void remove.run(row.${pk})}
              >
                <Text style={styles.buttonText}>Delete</Text>
              </Pressable>`
    : "";
  jsx += `      {loading ? (
        <ActivityIndicator />
      ) : error ? (
        <Text style={styles.error}>{error.message}</Text>
      ) : (
        <View style={styles.list}>
          {(data ?? []).map((row) => (
            <View key={${key}} style={styles.row}>
              <View style={styles.rowBody}>
${cells}
              </View>${del}
            </View>
          ))}
          {data?.length === 0 ? <Text style={styles.muted}>No rows yet.</Text> : null}
        </View>
      )}
`;

  return `${imports}
export default function ${pascal}Screen() {
${body}
  return (
    <View style={styles.list}>
${jsx}    </View>
  );
}
`;
}

/** A labelled control bound into the create form's state. Which kind it is was
 * decided by Saltcorn (`control`), not re-derived from a type spelling. */
function formControl(field) {
  const set = (value) => `(v) => setForm({ ...form, ${field.name}: ${value} })`;
  if (field.control === "checkbox") {
    return `        <View style={styles.switchRow}>
          <Switch value={form.${field.name}} onValueChange={${set("v")}} />
          <Text style={styles.label}>${field.label}</Text>
        </View>`;
  }
  const input =
    field.control === "number"
      ? `inputMode="decimal"
            value={String(form.${field.name})}
            onChangeText={${set("Number(v) || 0")}}`
      : `value={form.${field.name}}
            onChangeText={${set("v")}}`;
  return `        <View style={styles.field}>
          <Text style={styles.label}>${field.label}</Text>
          <TextInput
            style={styles.input}
            ${input}
          />
        </View>`;
}

/** The project root's guide for coding agents. Written once; agents append. */
function agentsMd(ctx) {
  const tables = ctx.tables.length
    ? ctx.tables.map((t) => `- \`${t.name}\` → \`src/screens/${t.pascal}.tsx\``).join("\n")
    : "- (none yet)";
  return `# ${ctx.app.name}

An Expo (React Native) application, served by Saltcorn on the web at
${ctx.app.url} and built into an Android APK or AAB with the admin UI's
**Build Android app** button (\`npm run build:android:<type>-<package>\`, e.g.
\`build:android:release-aab\`, by the application's "Build type" and "Package"
settings; the result lands in \`android-output/\`). The application ID, version,
icon and signing are the application's "Android app" settings in Saltcorn,
written into \`${ctx.runtime}/native.json\` on every build.

## Layout

| path | what it is |
|---|---|
| \`index.ts\` | the entry point, on every platform |
| \`app.config.js\` | Expo's configuration — reads the APK's settings from \`${ctx.runtime}/native.json\` |
| \`src/Root.tsx\` | the providers around the shell |
| \`src/App.tsx\` | the shell: header, nav, the current screen |
| \`src/routes.tsx\` | the routes, as data |
| \`src/navigation.tsx\` | the navigator: current path, \`navigate()\`, the browser's history |
| \`src/screens/\` | one screen per table — **yours to change** |
| \`src/theme.ts\` | colours and shared \`StyleSheet\` styles |
| \`android/\` | written by \`expo prebuild\` on every APK build — **generated**, not in git |
| \`${ctx.runtime}/\` | **generated** — see its own README |

${tables}

## Rules

1. **Never edit \`${ctx.runtime}/\`.** It is regenerated from the application's
   API on every build; your edits are lost. Read it to learn what data exists.
2. **Reach data through \`${ctx.client}\`**, or the hooks beside it. There is
   no database connection in this project and there is not meant to be.
3. **Screens use React Native's components and \`StyleSheet\` only** — no
   \`<div>\`, no \`className\`, no CSS files — because the same source is the
   web bundle and the APK.
4. **Build before reporting a change done**: \`npm run build\` type-checks every
   file against the generated client and exports the web bundle.
${
  ctx.auth
    ? `5. **Every screen requires a signed-in user**: \`App.tsx\` shows the login
   screen to anyone who is not.\n`
    : ""
}
## Adding data the API does not have

\`\`\`sh
feldspar api add-query --app ${ctx.app.subdomain} --name recentPosts \\
  --sql "SELECT * FROM posts ORDER BY published DESC LIMIT :n"
\`\`\`

The query becomes a typed method on \`${ctx.client}\` at the next build.
`;
}

// ---------------------------------------------------------------------------
// The two generators
// ---------------------------------------------------------------------------

/** The whole project, written once when the application is created. Saltcorn
 * writes the client, its helper, `schema.sql` and `SKILL.md` itself. */
function scaffold(ctx) {
  const files = [
    { path: "package.json", contents: packageJson(ctx) },
    { path: "app.config.js", contents: appConfigJs(ctx) },
    { path: "tsconfig.json", contents: TSCONFIG },
    { path: ".gitignore", contents: GITIGNORE },
    { path: "AGENTS.md", contents: agentsMd(ctx) },
    { path: "index.ts", contents: INDEX_TS },
    { path: "src/Root.tsx", contents: rootTsx(ctx) },
    { path: "src/App.tsx", contents: appTsx(ctx) },
    { path: "src/routes.tsx", contents: routesTsx(ctx) },
    { path: "src/navigation.tsx", contents: NAVIGATION_TSX },
    { path: "src/theme.ts", contents: THEME_TS },
    { path: "src/screens/Home.tsx", contents: homeTsx(ctx) },
  ];
  if (ctx.auth) {
    files.push({ path: "src/auth.tsx", contents: AUTH_TSX });
    files.push({ path: "src/Login.tsx", contents: LOGIN_TSX });
  }
  for (const table of ctx.tables) {
    files.push({ path: `src/screens/${table.pascal}.tsx`, contents: screenTsx(table) });
  }
  return files.concat(runtime(ctx));
}

/** The framework's own generated code, rewritten on every build. */
function runtime(ctx) {
  return [
    { path: at(ctx.runtime, "hooks.ts"), contents: hooksTs(ctx) },
    { path: at(ctx.runtime, "config.ts"), contents: configTs(ctx) },
    { path: at(ctx.runtime, "native.json"), contents: nativeJson(ctx) },
    { path: at(ctx.runtime, "README.md"), contents: runtimeReadme(ctx) },
  ];
}

module.exports = {
  sc_plugin_api_version: 1,
  plugin_name: "react-native",
  configuration_workflow,
  // A function of the module's settings, so the Android toolchain the admin
  // configured on the Modules tab reaches the APK build.
  frameworks: (configuration) => ({
    "react-native": {
      label: "React Native",
      description:
        "Saltcorn creates an Expo (React Native) project, generates a typed client and hooks " +
        "for your tables, and serves it on the web; an Android APK or AAB is one more button. " +
        "Pick a file store and a name.",
      config_fields,
      build,
      csp,
      builder_prompt,
      // What the builder agent's `check` runs before the application build.
      checks: ["typecheck"],
      targets: targets(configuration || {}),
      scaffold,
      runtime,
    },
  }),
};
